<?php require_once '../includes/functions.php';if(logged_in())redirect('user/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$pass=$_POST['password'];if(strlen($pass)<8)$error='Password must be at least 8 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'user'];redirect('user/dashboard.php');}catch(PDOException $e){$error='This email is already registered.';}}}$page_title='Create Account';require '../includes/header.php';?><section class="auth-layout"><div class="auth-photo" style="background-image:url('https://images.unsplash.com/photo-1500375592092-40eb2168fd21?w=1200')"><h1>Explore<br>Bangladesh</h1><p>Create your account and start your journey.</p></div><div class="auth-panel"><h2>Create your account</h2><p class="muted">Join and start planning your next trip.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" class="form-card"><?=csrf_field()?><label>Full Name<input name="name" required placeholder="Enter your name"></label><label>Email Address<input type="email" name="email" required placeholder="Enter your email"></label><label>Password<div class="password-field"><input id="register-password" type="password" name="password" minlength="8" required placeholder="Create a password" autocomplete="new-password"><button class="password-toggle" type="button" aria-controls="register-password" aria-label="Show password" aria-pressed="false">Show</button></div></label><button class="btn btn-primary btn-block">Register</button></form><p class="center">Already have an account? <a href="login.php">Login</a></p></div></section><?php require '../includes/footer.php';?>
